table.insert(minis,{p=m,pos=pet.pos,t0=os.clock()}) end local function infect() if inf then return end local ch=plr.Character local hd=ch and ch:FindFirstChild("Head") if not hd then return end local g,l=label(hd,"BURRITO INFECTION 0%",RED,260,40,3) inf={t0=os.clock(),lvl=0,gui=g,lbl=l} end local function cure() if not inf then return end if inf.gui then inf.gui:Destroy() end if inf.hl then inf.hl:Destroy() end local ch=plr.Character local hum=ch and ch:FindFirstChildOfClass("Humanoid") if hum then hum.WalkSpeed=16 end
local hd=ch and ch:FindFirstChild("Head") if hd then local g=label(hd,"...i feel normal again",WHITE,260,40,3) DB:AddItem(g,3) end inf=nil achieve("Cured!","blox-cola works on humans too") end function spawnItem(kind,at) local c=plr.Character local r=c and c:FindFirstChild("HumanoidRootPart") if not r and not at then return end local hit if at then hit=ground(at+Vector3.new(0,5,0),40) else hit=ground(r.Position+Vector3.new(math.random(-80,80),100,math.random(-80,80)),400) end if not hit then return end local f=Instance.new("Part") f.Name=kind f.Anchored=true f.CanCollide=false f.Material=Enum.Material.Neon local col,txt,tcol if kind=="food" then f.Shape=Enum.PartType.Ball f.Size=Vector3.new(1.6,1.6,1.6) col=Color3.fromRGB(220,30,30) txt="FOOD" tcol=Color3.fromRGB(255,220,0) elseif kind=="poison" then f.Shape=Enum.PartType.Cylinder f.Size=Vector3.new(1.8,1,1) col=TOX txt="POISON" tcol=TOX elseif kind=="churro" then f.Shape=Enum.PartType.Cylinder f.Size=Vector3.new(3,0.5,0.5) f.Material=Enum.Material.SmoothPlastic col=Color3.fromRGB(200,140,60) txt="CHURRO" tcol=Color3.fromRGB(255,170,60)
