function setPrompts(pet,mode) for _,x in ipairs(pet.prompts) do x:Destroy() end pet.prompts={} local function pr(text,key,gp,off,fn) local q=Instance.new("ProximityPrompt") q.Name=text q.ActionText=text q.ObjectText=(pet.evil and (pet.super and "SUPER EVIL " or "EVIL ") or pet.ultra and "ULTRA " or "").."("..pet.pers..") "..pet.nm q.KeyboardKeyCode=key q.GamepadKeyCode=gp q.HoldDuration=0 q.RequiresLineOfSight=false q.UIOffset=Vector2.new(0,off) q.Parent=pet.p q.Triggered:Connect(function(w) if w==plr and not pet.dying and not pet.dead then fn() end end) table.insert(pet.prompts,q) end local E,Rk,Fk=Enum.KeyCode.E,Enum.KeyCode.R,Enum.KeyCode.F if mode=="cute" then pr("Feed",E,Enum.KeyCode.ButtonX,0,function() if inv.food<1 then say(pet,"you have no food!! go find some on the map!") return end pet.mem.fed=pet.mem.fed+1 inv.food=inv.food-1 pet.hunger=math.min(100,pet.hunger+35) pet.sc=pet.sc+0.3 pet.spinT=os.clock() sparkle(pet.p,Color3.fromRGB(255,200,0)) say(pet,R(L.happy)) end) pr("Pet",Rk,Enum.KeyCode.ButtonY,80,function() pet.mem.pets=pet.mem.pets+1 if pet.beans then pet.sc=math.min(2,pet.sc+0.1) end pet.love=math.min(100,pet.love+25) pet.spinT=os.clock() sparkle(pet.p,Color3.fromRGB(255,120,200)) say(pet,R(L.pat)) end)
pr("Hug",Enum.KeyCode.G,Enum.KeyCode.ButtonL1,160,function() pet.mem.hugs=pet.mem.hugs+1 achieve("Hugger","the hats are huggable") if pet.beans then pet.sc=math.min(2,pet.sc+0.1) end pet.love=math.min(100,pet.love+15) pet.spinT=os.clock() sparkle(pet.p,Color3.fromRGB(255,120,200)) say(pet,pet.beans and "...hug... back..." or "hug!! <3") end) elseif mode=="evil" then if pet.evilfox then pr("Say Cool Fox",E,Enum.KeyCode.ButtonX,0,function() X.cure(pet,"...ding? ...you think im cool? ...POW. (happy)","Cool Fox","you calmed an evil fox") setPrompts(pet,"fox") end) elseif pet.tail then pr("Say Cool Tail",E,Enum.KeyCode.ButtonX,0,function() local r=plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") if not r then return end local d=pet.p.Position-r.Position local lv=r.CFrame.LookVector if Vector3.new(lv.X,0,lv.Z).Unit:Dot(Vector3.new(d.X,0,d.Z).Unit)<0.4 then say(pet,"youre not even LOOKING at me.") return end saveTail(pet) end) elseif pet.shoes then pr("Dance",E,Enum.KeyCode.ButtonX,0,function() X.cure(pet,"...wait. you WANT to dance? ...BAWK!! (happy bawk)","Dance Partner","you danced with your evil shoes") X.beansDance() end) elseif pet.clothes then pr("Fold",E,Enum.KeyCode.ButtonX,0,function() X.fold(pet) end) elseif pet.belt then pr("Say Cool Belt",E,Enum.KeyCode.ButtonX,0,function() X.cure(pet,"...you NOTICED me...? nobody notices a belt...","Notice Your Belt","you said cool belt") end) elseif pet.backpack then pr("Say Thank You",E,Enum.KeyCode.ButtonX,0,function() X.cure(pet,"...20 years... and thats the first time...","Thank Your Backpack","you thanked your backpack") headMsg("(it gave you a cookie)",WHITE,3) end) elseif pet.classic then pr("Share Lunch",E,Enum.KeyCode.ButtonX,0,function() X.unflat() X.cure(pet,"...nobodys eaten lunch with me since 2008...","Lunch Buddies","you shared lunch with a classic tshirt") end) elseif pet.ball then pr("Let It Win",E,Enum.KeyCode.ButtonX,0,function() X.cure(pet,"...you let me win? ...this is the best day of my life.","Good Sport","you let the basketball win") end) elseif pet.gear then pr("Put It Down",E,Enum.KeyCode.ButtonX,0,function() X.cure(pet,"...20 years... and nobody ever just let me be food...","Let It Be Lunch","you put down the food gear") end) elseif pet.helmet then pr("Pour Ranch",E,Enum.KeyCode.ButtonX,0,function() if inv.ranch<1 then say(pet,"you need RANCH. its on the map somewhere. crunch.") return end inv.ranch=inv.ranch-1 X.cure(pet,"...oh. oh thats actually really good.","Ranch Hand","you poured ranch on an evil salad helmet") end)
else pr("Feed Poison",E,Enum.KeyCode.ButtonX,0,function() if inv.poison<1 then say(pet,R(L.nopoison)) return end pet.mem.poison=pet.mem.poison+1 inv.poison=inv.poison-1 pet.poison=pet.poison+1 pet.stun=os.clock()+1.2 sparkle(pet.p,PURP) pet.hl.FillColor=(pet.super and BLACK or RED):Lerp(PURP,pet.poison/pet.need) say(pet,R(L.poisoned)) if pet.poison>=pet.need then die(pet) end end) pr("Throw Churro",Enum.KeyCode.T,Enum.KeyCode.ButtonR1,320,function() X.churro(pet) end) end pr("Pet",Rk,Enum.KeyCode.ButtonY,80,function() pet.flicker=os.clock()+1.2 pet.sc=pet.sc+0.1 say(pet,R(L.evilpet),"hat") end) pr("Slap",Fk,Enum.KeyCode.ButtonB,160,function() achieve("Burrito Slapper","nobody has EVER slapped a burrito") pet.mem.slaps=pet.mem.slaps+1 pet.stun=os.clock()+1 pet.sc=math.max(1,pet.sc-0.4) pet.rage=pet.rage*1.1 beans(pet.p.Position) say(pet,R(L.slap)) if pet.sc<3 then unEvil(pet) end end) pr("Hug",Enum.KeyCode.G,Enum.KeyCode.ButtonL1,240,function() if pet.evilbeans then X.twin(pet) return end local now=os.clock() pet.mem.hugs=pet.mem.hugs+1 pet.hugs=(pet.hugs or 0)+1 local hg=pet.hugs local pink=Color3.fromRGB(255,120,200) achieve("Hugger","you hugged a burrito. why.") pet.stun=now+3 pet.embarrass=hg<=2 and now+7 or 0 if hg>=3 then pet.flicker=now+3 end pet.hl.FillColor=(pet.super and BLACK or RED):Lerp(pink,math.min(1,hg/5)) if pet.fire then pet.fire.Size=math.max(1,(pet.super and 10 or 5)*(1-hg/5)) end sparkle(pet.p,pink) if pet.supremo then say(pet,"...no one... has ever... hugged our toe...","hat") if hg>=5 then redeem(pet) end return end
if hg==1 then say(pet,"...it's... warm...","hat") task.delay(3,function() if not pet.dead and pet.evil then say(pet,"...NO. I AM EVIL. I DO NOT HUG.") end end) elseif hg==2 then say(pet,"...why do you keep DOING that...") elseif hg==3 then say(pet,"...i don't know what this feeling is...","hat") elseif hg==4 then say(pet,"for 10 years... nobody... ever...") beans(pet.p.Position) task.delay(1.5,function() if not pet.dead and pet.evil then say(pet,"I'M STILL HERE! KEEP GOING!","hat") end end) else adoptBeans(pet.p.CFrame+Vector3.new(0,3,0)) unEvil(pet) say(pet,"you didn't give up on me...","hat") achieve("True Ending","5 hugs. the burrito became good. everyone wins.") end end) elseif mode=="inside" then pr("Untuck",E,Enum.KeyCode.ButtonX,0,function() X.untuck(pet) end) pr("Eat It Back",Rk,Enum.KeyCode.ButtonY,80,function() X.eatBack(pet) end) elseif mode=="fox" then pr("Pet",Rk,Enum.KeyCode.ButtonY,0,function() sparkle(pet.p,Color3.fromRGB(255,140,0)) pet.spinT=os.clock() say(pet,R(X.fox)) end)
pr("Hug",Enum.KeyCode.G,Enum.KeyCode.ButtonL1,80,function() achieve("Hugger","the hats are huggable") pet.spinT=os.clock() say(pet,"ding! (thats a happy ding)") end) elseif mode=="ultra" then pr("Pet",Rk,Enum.KeyCode.ButtonY,0,function() sparkle(pet.p,GOLD) pet.spinT=os.clock() say(pet,R(L.ultra)) end) pr("Hug",Enum.KeyCode.G,Enum.KeyCode.ButtonL1,80,function() achieve("Hugger","the hats are huggable") sparkle(pet.p,GOLD) pet.spinT=os.clock() say(pet,"...thank you. for everything.") end) end end function mk(h,i,head,acc,kind) local p=h:Clone() for _,d in ipairs(p:GetDescendants()) do if d:IsA("JointInstance") or d:IsA("WeldConstraint") or d:IsA("Attachment") then d:Destroy() end end p.Anchored=false p.CanCollide=true p.CFrame=h.CFrame p.Parent=F local m=p:FindFirstChildOfClass("SpecialMesh")
local g=Instance.new("BillboardGui") g.Size=UDim2.new(0,230,0,70) g.AlwaysOnTop=true g.MaxDistance=150 g.Parent=p local s=Instance.new("TextLabel") s.Size=UDim2.new(1,0,0.6,0) s.BackgroundColor3=WHITE s.TextColor3=BLACK s.TextScaled=true s.Font=Enum.Font.FredokaOne s.Text="" s.Visible=false s.Parent=g Instance.new("UICorner").Parent=s local st=Instance.new("TextLabel") st.Size=UDim2.new(1,0,0.4,0) st.Position=UDim2.new(0,0,0.6,0) st.BackgroundTransparency=1 st.TextColor3=WHITE st.TextStrokeTransparency=0 st.TextScaled=true st.Font=Enum.Font.GothamBold st.Text="" st.Parent=g local pet={pers=kind=="supremo" and "chaotic" or kind=="beans" and "sweet" or kind=="churro" and "shy" or kind=="evilbeans" and "grumpy" or PKEYS[math.random(#PKEYS)],mem={fed=0,pets=0,hugs=0,slaps=0,poison=0,ate=0},made=os.clock(),p=p,m=m,nm=kind=="beans" and "Beans" or kind=="summoned" and "Summoned Burrito" or kind=="tiny" and "Tiny Burrito" or kind=="classic" and "Classic T-Shirt" or kind=="evilbeans" and "Evil Beans" or kind=="churro" and "Churro Jr." or kind=="supremo" and "EL BURRITO SUPREMO" or h.Parent.Name,acc=acc,innocent=kind=="innocent" or kind=="beans" or kind=="churro" or kind=="tiny",tail=kind=="tail",churro=kind=="churro",shoes=kind=="legs",belt=kind=="belt",ball=kind=="ball",backpack=kind=="backpack",classic=kind=="classic",gear=kind=="gear",clothes=kind=="clothes",helmet=kind=="helmet",evilbeans=kind=="evilbeans",beans=kind=="beans",supremo=kind=="supremo",s0=p.Size,ms0=m and m.Scale,rot=head and (head.CFrame:Inverse()*h.CFrame).Rotation or CFrame.new(),sc=1,hunger=60,love=60,poison=0,need=3,rage=1,survive=0,evil=false,falling=true,i=i,say=s,st=st,g=g,t0=0,nxt=os.clock()+math.random(5,9),blink=0,stun=0,lunge=0,flicker=0,hitT=0,spinT=-10,yaw=0,dyaw=0,ph=0,amp=0,wnext=0,prompts={},parts={},w={},pu={},br={},legs={},feet={},arms={},xw={},xp={},teeth={}} setPrompts(pet,"cute") table.insert(pets,pet) task.delay(1.5,function() if p.Parent then p.Anchored=true p.CanCollide=false pet.pos=p.Position pet.born=os.clock() local function add(q) table.insert(pet.parts,q) return q end for k=1,2 do pet.w[k]=add(part(Vector3.one,WHITE,nil,true)) pet.pu[k]=add(part(Vector3.one,BLACK,nil,true)) pet.br[k]=add(part(Vector3.one,BLACK)) pet.legs[k]=add(part(Vector3.one,LIMB)) pet.feet[k]=add(part(Vector3.one,LIMB,nil,true)) pet.arms[k]=add(part(Vector3.one,LIMB)) pet.xw[k]=add(part(Vector3.one,PURP,Enum.Material.Neon,true)) pet.xp[k]=add(part(Vector3.one,BLACK,nil,true)) end
pet.mo=add(part(Vector3.one,BLACK,nil,true)) for k=1,6 do pet.teeth[k]=add(part(Vector3.one,Color3.fromRGB(235,225,190))) end pet.falling=false if pet.gear or kind=="summoned" then goEvil(pet) elseif pet.evilbeans then pet.tophat=add(part(Vector3.one,BLACK)) pet.tophat.Shape=Enum.PartType.Cylinder pet.brim=add(part(Vector3.one,BLACK)) pet.brim.Shape=Enum.PartType.Cylinder goEvil(pet) elseif pet.supremo then pet.sc=6 goEvil(pet) goSuper(pet) pet.need=8 say(pet,R(L.supremo)) achieve("THE APOCALYPSE","you flushed 3 burritos. EL BURRITO SUPREMO has risen.") else say(pet,pet.beans and "*sniff* ...you saved me? im Beans." or pet.churro and "*crumbles* ...you looked at me. im Churro Jr." or pet.tail and "...sssswish. finally. im not BEHIND you anymore." or pet.shoes and "bawk! i mean... hi!" or pet.clothes and "...im just a jacket. totally normal jacket." or pet.belt and "...hi. im holding your pants up. youre welcome." or pet.backpack and "...you never look inside me..." or pet.classic and "...we were here FIRST. since 2006." or pet.gear and "...we remember EVERY bite." or pet.ball and "*boing* ...wanna play?" or pet.nm=="Tiny Burrito" and "...thank you for the hug." or pet.helmet and "crunch. hello. have you had water today?" or pet.innocent and R(L.innocent) or R(L.born)) if pet.innocent and not pet.beans and not pet.churro then achieve("Innocent Hat","one of your hats has no burrito!") end end end end) end local function wander(pet,pos,rpos,now) if now>pet.wnext then pet.wnext=now+math.random(3,7) if math.random()<0.35 then pet.wt=nil else local a=math.random()*math.pi*2 local rr=math.random(6,22) pet.wt=rpos+Vector3.new(math.cos(a)*rr,0,math.sin(a)*rr) end end if pet.wt then return pet.wt,9 end return pos,0
end function X.kindOf(a,h) local n=a.Name:lower() local at=a.AccessoryType local T=Enum.AccessoryType if n:find("tail") or h:FindFirstChild("WaistBackAttachment") then return "tail" end if at==T.Waist then return "belt" end if at==T.LeftShoe or at==T.RightShoe or n:find("shoe") or n:find("boot") or n:find("sneaker") or n:find("sock") then return "legs" end if at==T.Jacket or at==T.Sweater or at==T.Shirt or at==T.TShirt or at==T.Pants or at==T.Shorts or at==T.DressSkirt or h:FindFirstChildOfClass("WrapLayer") then return "clothes" end if at==T.Back or h:FindFirstChild("BodyBackAttachment") then return "backpack" end if (n:find("ball") or n:find("basket")) and not n:find("cap") and not n:find("hat") then return "ball" end if n:find("helmet") or n:find("mask") or (h.Size.X>2.4 and h.Size.Y>2.4 and h.Size.Z>2.2) then return "helmet" end if math.random()<0.25 then return "innocent" end
end function X.cure(pet,msg,ach,desc) release(pet) unEvil(pet) pet.innocent=true sparkle(pet.p,GOLD) say(pet,msg,"hat") achieve(ach,desc) end function X.fold(pet) pet.folds=(pet.folds or 0)+1 sparkle(pet.p,WHITE) if pet.folds==1 then say(pet,"...did you just... FOLD me?","hat") elseif pet.folds==2 then say(pet,"...nobody folds me. they just throw me on the chair...","hat") else X.cure(pet,"...i feel... so organized...","Fold Your Clothes","you folded an evil jacket") end end function X.unwrap(pet) local tw=pet.twrap if not tw then return end for _,q in ipairs(tw.vis or {}) do q:Destroy() end if tw.tort then tw.tort:Destroy() end if eating==tw.ch then eating=nil end
if tw.r.Parent then tw.r.CFrame=tw.from tw.r.Anchored=false end tw.hum.WalkSpeed=16 tw.hum.JumpPower=50 if tw.style=="classic" then X.flatten(tw.hum,20) end pet.twrap=nil end function X.tortilla(tw) local tp=part(Vector3.new(4,3.6,3.6),TAN) tp.Shape=Enum.PartType.Cylinder tp.CFrame=CFrame.new(tw.r.Position-Vector3.new(0,0.75,0))*CFrame.Angles(0,0,math.pi/2) label(tp,"mmf!! (with lettuce)",Color3.fromRGB(120,220,80),220,26,3) tw.tort=tp end function X.grabStart(pet) local tw=pet.twrap tw.vis={} local pos=tw.r.Position local st=tw.style local function v(sz,col,cf,shape) local q=part(sz,col) if shape then q.Shape=shape end q.CFrame=cf table.insert(tw.vis,q) return q end if st=="clothes" then local q=v(Vector3.new(4,3.6,3.6),TAN,CFrame.new(pos-Vector3.new(0,0.75,0))*CFrame.Angles(0,0,math.pi/2),Enum.PartType.Cylinder) label(q,"mmf!! (with lettuce)",Color3.fromRGB(120,220,80),220,26,3) say(pet,"one human wrap. with lettuce.") achieve("Thats a Wrap!","an evil jacket rolled you into a wrap") elseif st=="belt" then local q=v(Vector3.new(5,0.6,0.6),Color3.fromRGB(190,130,60),CFrame.new(pos)*CFrame.Angles(0,0,0.7),Enum.PartType.Cylinder) v(Vector3.new(5,0.6,0.6),Color3.fromRGB(190,130,60),CFrame.new(pos)*CFrame.Angles(0,0,-0.7),Enum.PartType.Cylinder) label(q,"TIED IN A PRETZEL (salty) - a fox or Beans can untie you",Color3.fromRGB(255,220,150),340,30,3) say(pet,"twist. youre a SNACK now.") achieve("Pretzeled","a belt tied you in a knot")
elseif st=="classic" then local lv=tw.r.CFrame.LookVector local q=v(Vector3.new(4,5,0.6),Color3.fromRGB(230,190,120),CFrame.lookAt(pos+lv*1.3,pos+lv*3)) v(Vector3.new(4,5,0.6),Color3.fromRGB(230,190,120),CFrame.lookAt(pos-lv*1.3,pos)) label(q,"SQUISH",WHITE,160,30,3) say(pet,"SANDWICH TIME.") else local nm=pet.nm:lower() local txt,col="FOLDED LIKE A TACO",Color3.fromRGB(240,200,80) if nm:find("pizza") then txt,col="MELTED LIKE CHEESE (stretchy)",Color3.fromRGB(255,170,60) elseif nm:find("burger") then txt,col="STACKED IN A CHEEZBURGER",Color3.fromRGB(150,90,40) end local q=v(Vector3.new(4,4,4),col,CFrame.new(pos)) q.Transparency=0.4 label(q,txt,WHITE,280,30,3) say(pet,"we remember EVERY bite.") end end function X.flatten(hum,dur) local bd=hum:FindFirstChild("BodyDepthScale") if bd then if not X.flatOld then X.flatOld=bd.Value end bd.Value=0.1 end X.flatUntil=os.clock()+dur X.flatHum=hum headMsg("youre FLAT now. 2D. share lunch with the tshirt to un-flat!",WHITE,4) achieve("Paper Thin","a classic tshirt flattened you") end function X.unflat() if X.flatHum then local bd=X.flatHum:FindFirstChild("BodyDepthScale") if bd and X.flatOld then bd.Value=X.flatOld end end X.flatHum=nil X.flatOld=nil X.flatUntil=nil end function X.stuff(pet,r,hum) local base=r.Position+Vector3.new(0,900,0) local dark=math.random()<0.25 local room=Instance.new("Model") room.Name="BackpackRoom" room.Parent=F
local col=dark and Color3.fromRGB(10,10,15) or Color3.fromRGB(120,80,160) local function wall(sz,off,c) local w=part(sz,c or col) w.CanCollide=true w.Position=base+off w.Parent=room return w end wall(Vector3.new(30,1,30),Vector3.new(0,-0.5,0),dark and Color3.fromRGB(5,5,8) or Color3.fromRGB(200,160,120)) wall(Vector3.new(30,14,1),Vector3.new(0,7,15)) wall(Vector3.new(30,14,1),Vector3.new(0,7,-15)) wall(Vector3.new(1,14,30),Vector3.new(15,7,0)) wall(Vector3.new(1,14,30),Vector3.new(-15,7,0)) wall(Vector3.new(30,1,30),Vector3.new(0,14,0)) local sign=wall(Vector3.new(1,1,1),Vector3.new(0,6,0)) sign.Transparency=1 sign.CanCollide=false if dark then label(sign,"...you looked inside. now youre part of the collection.",RED,360,40,0) achieve("The Bottomless Backpack","there is no exit sign") else local lp=wall(Vector3.new(1,1,1),Vector3.new(0,12,0),Color3.fromRGB(255,220,150)) lp.Material=Enum.Material.Neon local pl=Instance.new("PointLight") pl.Range=40 pl.Brightness=2 pl.Color=Color3.fromRGB(255,210,150) pl.Parent=lp local bb=wall(Vector3.new(4,3,4),Vector3.new(6,1.5,6),Color3.fromRGB(200,60,60)) local sm=Instance.new("SpecialMesh") sm.MeshType=Enum.MeshType.Sphere sm.Parent=bb local ck=wall(Vector3.new(0.3,1.2,1.2),Vector3.new(-5,0.2,4),Color3.fromRGB(150,90,40)) ck.Shape=Enum.PartType.Cylinder label(ck,"cookie",WHITE,80,20,1) for n=1,8 do wall(Vector3.new(0.2,0.2,2),Vector3.new(math.random(-12,12),0.1,math.random(-12,12)),Color3.fromRGB(255,210,0)) end local sk=wall(Vector3.new(1,0.4,2),Vector3.new(-8,0.2,-7),Color3.fromRGB(240,240,255)) label(sk,"one sock",WHITE,90,20,1)
label(sign,"inside the backpack. its bigger in here :)",Color3.fromRGB(255,220,150),340,40,0) achieve("Inside the Backpack","its cozy in here") end local door=wall(Vector3.new(4,7,0.5),Vector3.new(0,3.5,14.3),Color3.fromRGB(90,60,30)) X.inPack={pet=pet,from=r.CFrame,room=room,tries=0} eating=hum.Parent pet.stun=os.clock()+999 local q=Instance.new("ProximityPrompt") q.ActionText=dark and "Search for the Exit" or "Say Thanks & Exit" q.ObjectText=dark and "???" or "Door (front pocket)" q.HoldDuration=0 q.RequiresLineOfSight=false q.MaxActivationDistance=10 q.Parent=door q.Triggered:Connect(function(w) local ip=X.inPack if w~=plr or not ip then return end if dark and ip.tries<2 then ip.tries=ip.tries+1 headMsg(ip.tries==1 and "...its not here..." or "...wait... theres a crack of light...",WHITE,2) return end local rr=plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") if rr then rr.CFrame=ip.from end X.inPack=nil eating=nil room:Destroy() ip.pet.stun=os.clock()+2 if not ip.pet.dead then X.cure(ip.pet,"...20 years... and thats the first time...","Thank Your Backpack","you thanked your backpack") end headMsg("(you found a cookie in there)",WHITE,3) end) r.CFrame=CFrame.new(base+Vector3.new(0,3,0)) say(pet,"zzzzzip. ...welcome.") end
function X.crumbStart(hum,roll) if X.crumb then return end X.crumb={jumps=0,roll=roll,hum=hum,parts={},t0=os.clock()} local g=part(Vector3.new(1.2,0.6,2),WHITE) label(g,"seagull",WHITE,100,20,1.2) table.insert(X.crumb.parts,g) X.crumb.gull=g if roll then local b=part(Vector3.new(7,7,7),Color3.fromRGB(205,150,70),nil,true) b.Transparency=0.15 table.insert(X.crumb.parts,b) X.crumb.ball=b local q=Instance.new("ProximityPrompt") q.ActionText="Butter" q.ObjectText="Bread Roll (you)" q.HoldDuration=0 q.RequiresLineOfSight=false q.MaxActivationDistance=15 q.Parent=b q.Triggered:Connect(function(w) if w==plr then if X.sword then achieve("Butter Knife","your sword buttered you. its dream came true.") end X.crumbEnd(X.sword and "your sword: ...stand back. im a professional. *spreeead*" or "*spreeead* ...ahh. thats the spot.") end end) headMsg("you got ROLLED into a BREAD ROLL! press BUTTER to un-roll!",Color3.fromRGB(255,200,120),5) achieve("Roll Model","a whole bread roll in your shirt") else headMsg("CRUMB CURSE! theres a crumb in your shirt. JUMP 3 TIMES to shake it out!",Color3.fromRGB(255,200,120),5) achieve("Crumbs","just one crumb. so annoying.") X.crumb.jc=hum.StateChanged:Connect(function(_,st) local cr=X.crumb if st==Enum.HumanoidStateType.Jumping and cr then cr.jumps=cr.jumps+1 if cr.jumps>=3 then achieve("Shake It Out","you shook out the crumb") X.crumbEnd("*the crumb falls out. the seagull eats it and leaves happy.*") end end end) end
end function X.crumbEnd(msg) local cr=X.crumb if not cr then return end X.crumb=nil if cr.jc then cr.jc:Disconnect() end for _,q in ipairs(cr.parts) do q:Destroy() end if msg then headMsg(msg,WHITE,4) end end function X.beansDance() for _,o in ipairs(pets) do if o.beans and not o.dead and not o.falling then o.spinT=os.clock() say(o,"...i wanna learn too!! *dances for the first time*") achieve("Beans Can Dance","beans danced for the first time") return end end end function X.worldStart(pet) if X.world then return end local r=plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") if not r then return end local Lg=game:GetService("Lighting") X.world={pet=pet,hugs=0,old={Lg.Ambient,Lg.OutdoorAmbient,Lg.FogColor,Lg.FogStart,Lg.FogEnd,Lg.ClockTime}} Lg.Ambient=Color3.fromRGB(120,80,40) Lg.OutdoorAmbient=Color3.fromRGB(150,100,50) Lg.FogColor=Color3.fromRGB(215,170,100) Lg.FogStart=0 Lg.FogEnd=150 Lg.ClockTime=0 local wpos=r.Position+r.CFrame.LookVector*12+Vector3.new(0,4,0) local wall=part(Vector3.new(16,12,1.5),TAN) wall.CanCollide=true wall.CFrame=CFrame.lookAt(wpos,r.Position+Vector3.new(0,4,0))
local _,wl=label(wall,"THE WHOLE WORLD IS INSIDE A BURRITO. HUG THE WALLS! (0/8)",Color3.fromRGB(255,220,150),420,50,8) local rain=part(Vector3.new(30,1,30),WHITE) rain.Transparency=1 local pe=Instance.new("ParticleEmitter") pe.Color=ColorSequence.new(Color3.fromRGB(255,210,60)) pe.Size=NumberSequence.new(0.3) pe.Rate=40 pe.Speed=NumberRange.new(10,15) pe.EmissionDirection=Enum.NormalId.Bottom pe.Lifetime=NumberRange.new(3,4) pe.Parent=rain X.world.wall=wall X.world.rain=rain local q=Instance.new("ProximityPrompt") q.ActionText="Hug the Wall" q.ObjectText="Tortilla Sky" q.HoldDuration=0 q.RequiresLineOfSight=false q.MaxActivationDistance=20 q.Parent=wall q.Triggered:Connect(function(w) local wd=X.world if w~=plr or not wd then return end wd.hugs=wd.hugs+1 wl.Text=string.format("HUG THE WALLS! (%d/8)",wd.hugs) sparkle(wall,Color3.fromRGB(255,150,200)) for _,o in ipairs(pets) do if not o.dead then o.spinT=os.clock() end end if wd.hugs>=8 then X.worldEnd() end end) for _,o in ipairs(pets) do if not o.dead and not o.falling then say(o,o.beans and "EVERYONE. HUG THE WALLS." or "HUG THE WALLS!!","hat") end end if gerald then gerald.Text="...this one wasnt even my fault." end headMsg("a burrito ate the WHOLE WORLD. hug the walls 8 times!",Color3.fromRGB(255,200,120),6) achieve("Dessert","a burrito swallowed the earth") end function X.worldEnd() local wd=X.world if not wd then return end X.world=nil
local Lg=game:GetService("Lighting") Lg.Ambient,Lg.OutdoorAmbient,Lg.FogColor,Lg.FogStart,Lg.FogEnd,Lg.ClockTime=table.unpack(wd.old) wd.wall:Destroy() wd.rain:Destroy() local pt=wd.pet if pt and not pt.dead then local pos=pt.pos say(pt,"...i wasnt hungry for food... i was hungry for THIS.","hat") task.delay(2,function() if not pt.dead then clean(pt) end local md,tp=template("Tiny Burrito",CFrame.new(pos+Vector3.new(0,3,0)),Vector3.new(1.4,0.8,0.8)) mk(tp,#pets+1,nil,nil,"tiny") md:Destroy() end) end if gerald then gerald.Text="...8 billion people just hugged a burrito. from the inside." end achieve("8 Billion Hugs","you hugged the world free. it still rains cheese on tuesdays.") end function X.dunkStart(pet,r,hum,ch,flat) local hit=ground(r.Position+flat*10+Vector3.new(0,10,0),60) local gp=hit and hit.Position or r.Position+flat*10-Vector3.new(0,3,0) local rim=gp+Vector3.new(0,10,0) local vis={} local ring=part(Vector3.new(0.3,4,4),Color3.fromRGB(255,90,0),Enum.Material.Neon) ring.Shape=Enum.PartType.Cylinder ring.CFrame=CFrame.new(rim)*CFrame.Angles(0,0,math.pi/2) table.insert(vis,ring) local bb=part(Vector3.new(6,4,0.3),WHITE) bb.CFrame=CFrame.lookAt(rim+Vector3.new(0,2,0)-flat*2.5,rim+Vector3.new(0,2,0)) table.insert(vis,bb)
local pole=part(Vector3.new(0.5,12,0.5),Color3.fromRGB(80,80,80)) pole.Position=gp+Vector3.new(0,6,0)-flat*3 table.insert(vis,pole) label(ring,"net",WHITE,60,20,-1.5) for _,x in ipairs(ch:GetDescendants()) do if x:IsA("BasePart") or x:IsA("Decal") then if x~=r then x.Transparency=1 end end end pet.dunk={t0=os.clock(),n=0,rim=rim,vis=vis,ch=ch,r=r,hum=hum,from=r.CFrame} eating=ch r.Anchored=true hum.WalkSpeed=0 hum.JumpPower=0 pet.stun=os.clock()+10 say(pet,"*GULP* ...you got NEXT.") headMsg("youre INSIDE the basketball. press LET IT WIN to stop the dunking!",WHITE,4) end function X.dunkEnd(pet,full) local dk=pet.dunk if not dk then return end pet.dunk=nil for _,q in ipairs(dk.vis) do q:Destroy() end for _,x in ipairs(dk.ch:GetDescendants()) do if (x:IsA("BasePart") and x~=dk.r) or x:IsA("Decal") then x.Transparency=0 end end if dk.r.Parent then dk.r.CFrame=CFrame.new(dk.rim-Vector3.new(0,7,0)) dk.r.Anchored=false end dk.hum.WalkSpeed=16 dk.hum.JumpPower=50 if eating==dk.ch then eating=nil end
pet.stun=os.clock()+3 if full then say(pet,"...good game.") local tr=part(Vector3.new(1,2,1),GOLD,Enum.Material.Neon) tr.Anchored=false tr.CanCollide=true tr.Position=dk.rim-Vector3.new(0,5,0) label(tr,"trophy (you didnt ask for this)",GOLD,240,24,1.5) DB:AddItem(tr,30) achieve("Slam Dunked x7","you got dunked 7 times. buzzer beater.") end end function X.findBurrito(fox) local best,bd=nil,200 for _,o in ipairs(pets) do if o~=fox and o.evil and not o.dead and not o.dying and not o.falling and o.pos and not o.ball and not o.superfox and not o.tail and not o.clothes and not o.shoes and not o.helmet and not o.belt and not o.backpack and not o.classic and not o.gear and not o.eat then local dd=(o.pos-fox.pos).Magnitude if dd<bd then best,bd=o,dd end end end return best end function X.carryStart(pet,r,hum,ch) pet.carry={ch=ch,r=r,hum=hum,from=r.CFrame,t0=os.clock()} eating=ch r.Anchored=true hum.WalkSpeed=0 hum.JumpPower=0 pet.carry.target=X.findBurrito(pet)
if not pet.carry.target then local a=math.random()*math.pi*2 local md,tp=template("Summoned Burrito",CFrame.new(pet.pos+Vector3.new(math.cos(a)*15,6,math.sin(a)*15)),Vector3.new(2,1.1,1.1)) tp.Color=Color3.fromRGB(170,110,60) mk(tp,#pets+1,nil,nil,"summoned") md:Destroy() say(pet,"ding. ...i SUMMONED one.") else say(pet,"ding. youre going to see a friend of mine.") end headMsg("a SUPER EVIL FOX grabbed you! its carrying you to a burrito!! (say cool fox!)",Color3.fromRGB(255,140,0),4) end function X.carryEnd(pet,keep) local cr=pet.carry if not cr then return end pet.carry=nil if not keep then if cr.r.Parent then cr.r.Anchored=false end cr.hum.WalkSpeed=16 cr.hum.JumpPower=50 if eating==cr.ch then eating=nil end end end function X.goEvilFox(pet) pet.fox=true pet.evilfox=true pet.tail=false goEvil(pet) end function X.goSuperFox(pet)
pet.superfox=true pet.super=true pet.need=5 if pet.hl then pet.hl.FillColor=BLACK pet.hl.OutlineColor=Color3.fromRGB(255,120,0) end if pet.fire then pet.fire.Color=Color3.fromRGB(255,120,0) pet.fire.SecondaryColor=BLACK pet.fire.Size=10 end boom(pet.p.Position,6) setPrompts(pet,"evil") say(pet,"ding... i have new friends. theyre HUNGRY.") achieve("Super Evil Fox","it feeds you to the burritos now") end function X.churro(pet) if inv.churro<1 then say(pet,"no churro? ...good.") return end inv.churro=inv.churro-1 local now=os.clock() if pet.hyperT and now<pet.hyperT then X.confetti(pet) return end pet.hyperT=now+10 pet.stun=now+10 say(pet,"WAIT IM NOT EVIL ANYMORE IM JUST SO HAPPY WHAT IS SUGAR","hat") achieve("Churrito","you threw a churro into a burrito") task.delay(10,function() if not pet.dead and pet.evil and not pet.dying then unEvil(pet) say(pet,"...zzz... *sugar crash* ...i feel cute again.","hat") end end) end function X.confetti(pet)
local pos=pet.p.Position boom(pos,6) ghost(pet,"...that was the best day of my life.") for n=1,40 do local b=part(Vector3.one*0.4,Color3.fromHSV(math.random(),0.8,1),Enum.Material.Neon) b.Anchored=false b.CanCollide=true b.CustomPhysicalProperties=PhysicalProperties.new(0.01,0.3,0.5) b.Position=pos b.AssemblyLinearVelocity=Vector3.new(math.random(-40,40),math.random(30,60),math.random(-40,40)) DB:AddItem(b,6) end clean(pet) achieve("Cinnamon Confetti","two churros. sugar overload. beautiful.") end function X.untuck(pet) local e=pet.eat if not e or e.done then return end local d=pet.pos-e.r.Position d=Vector3.new(d.X,0,d.Z) d=d.Magnitude>0.1 and d.Unit or Vector3.new(1,0,0) local sz=pet.p.Size.Magnitude*0.5 release(pet) if e.r.Parent then e.r.CFrame=CFrame.new(pet.pos+d*(sz+3)) end beans(pet.pos) pet.stun=os.clock()+3 setPrompts(pet,"evil") say(pet,"NOOOO NOT THE TUCK!!") task.delay(2,function() if not pet.dead then say(pet,"...nobody... saw that... right?") end end)
achieve("Every Trap Has a Tuck","you untucked a burrito from the inside") end function X.eatBack(pet) local e=pet.eat if not e or e.done then return end e.bites=(e.bites or 0)+1 pet.sc=math.max(1,pet.sc-0.8) say(pet,e.bites==1 and "...are you EATING MY BEANS?!" or "THOSE ARE MY BEAN ORGANS!!") if e.bites>=3 then local pos=pet.pos release(pet) clean(pet) local hit=ground(pos+Vector3.new(0,5,0),40) local bl=part(Vector3.new(6,0.2,6),TAN) bl.CanCollide=true bl.Position=(hit and hit.Position or pos)+Vector3.new(0,0.1,0) label(bl,"cozy tortilla blanket (very embarrassed)",TAN,280,30,2) DB:AddItem(bl,60) headMsg("...youre kind of cozy actually.",WHITE,4) achieve("Uno Reverse","it ate you. you ate it back.") end end
function X.twin(pet) pet.evilbeans=false for _,q in ipairs({pet.tophat,pet.brim}) do if q then q.Anchored=false q.CanCollide=true DB:AddItem(q,30) end end if pet.tophat then label(pet.tophat,"free top hat :)",WHITE,160,24,1.5) end pet.tophat=nil pet.brim=nil unEvil(pet) pet.beans=true pet.innocent=true pet.nm="Beans (twin)" setPrompts(pet,"cute") say(pet,"...ive waited my whole life for someone to say sorry...","hat") achieve("Sorry From All Of Us","you hugged evil beans. now there are two beans.") end function X.spawnEvilBeans() local r=plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") if not r or not F.Parent then return end
